[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Fuel Price Trends &amp; Policy Impact Analysis (2020–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface2: #22263a;
    --border: #2d3148;
    --accent: #4f8ef7;
    --accent2: #f7c44f;
    --accent3: #4fd4a0;
    --accent4: #f7714f;
    --text: #e8eaf0;
    --text-muted: #8890a8;
    --red: #f05252;
    --green: #31c48d;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    font-size: 14px;
    line-height: 1.6;
  }
  /* HEADER */
  .report-header {
    background: linear-gradient(135deg, #0f1117 0%, #1a2040 50%, #0f1117 100%);
    border-bottom: 1px solid var(--border);
    padding: 48px 64px 36px;
    position: relative;
    overflow: hidden;
  }
  .report-header::before {
    content: '';
    position: absolute;
    top: -60px; right: -60px;
    width: 320px; height: 320px;
    background: radial-gradient(circle, rgba(79,142,247,0.15) 0%, transparent 70%);
    border-radius: 50%;
  }
  .report-header::after {
    content: '';
    position: absolute;
    bottom: -40px; left: 20%;
    width: 200px; height: 200px;
    background: radial-gradient(circle, rgba(247,196,79,0.08) 0%, transparent 70%);
    border-radius: 50%;
  }
  .header-label {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 12px;
  }
  .header-title {
    font-size: 36px;
    font-weight: 700;
    letter-spacing: -0.5px;
    color: #fff;
    line-height: 1.2;
    margin-bottom: 12px;
  }
  .header-subtitle {
    font-size: 16px;
    color: var(--text-muted);
    max-width: 680px;
    margin-bottom: 28px;
  }
  .header-meta {
    display: flex;
    gap: 32px;
    font-size: 12px;
    color: var(--text-muted);
  }
  .header-meta span strong { color: var(--text); margin-right: 4px; }

  /* MAIN LAYOUT */
  .container { max-width: 1280px; margin: 0 auto; padding: 0 48px; }

  /* SECTION */
  .section {
    padding: 48px 0 16px;
    border-bottom: 1px solid var(--border);
  }
  .section:last-child { border-bottom: none; }
  .section-header {
    display: flex;
    align-items: baseline;
    gap: 16px;
    margin-bottom: 28px;
  }
  .section-number {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2px;
    color: var(--accent);
    text-transform: uppercase;
    white-space: nowrap;
  }
  .section-title {
    font-size: 22px;
    font-weight: 600;
    color: #fff;
  }
  .section-desc {
    font-size: 13px;
    color: var(--text-muted);
    max-width: 760px;
    margin-bottom: 24px;
  }

  /* KPI CARDS */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 40px;
  }
  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 18px 16px;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: var(--accent);
  }
  .kpi-card.accent2::before { background: var(--accent2); }
  .kpi-card.accent3::before { background: var(--accent3); }
  .kpi-card.accent4::before { background: var(--accent4); }
  .kpi-card.red::before { background: var(--red); }
  .kpi-label {
    font-size: 11px;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-muted);
    margin-bottom: 8px;
  }
  .kpi-value {
    font-size: 28px;
    font-weight: 700;
    color: #fff;
    letter-spacing: -1px;
    line-height: 1;
    margin-bottom: 4px;
  }
  .kpi-sub {
    font-size: 12px;
    color: var(--text-muted);
  }
  .kpi-badge {
    display: inline-block;
    font-size: 10px;
    font-weight: 600;
    padding: 2px 6px;
    border-radius: 4px;
    margin-top: 6px;
  }
  .badge-up { background: rgba(49,196,141,0.15); color: var(--green); }
  .badge-dn { background: rgba(240,82,82,0.15); color: var(--red); }

  /* CHART CONTAINERS */
  .chart-grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
  }
  .chart-grid-3 {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
  }
  .chart-box {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 20px 16px;
  }
  .chart-box.full-width { grid-column: 1 / -1; }
  .chart-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 4px;
  }
  .chart-subtitle {
    font-size: 11px;
    color: var(--text-muted);
    margin-bottom: 16px;
  }
  .chart-wrapper {
    position: relative;
  }

  /* TABLES */
  .data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
  }
  .data-table th {
    text-align: left;
    padding: 8px 12px;
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-muted);
    border-bottom: 1px solid var(--border);
  }
  .data-table td {
    padding: 9px 12px;
    border-bottom: 1px solid rgba(45,49,72,0.5);
    color: var(--text);
  }
  .data-table tr:last-child td { border-bottom: none; }
  .data-table tr:hover td { background: rgba(79,142,247,0.04); }
  .data-table .num { font-variant-numeric: tabular-nums; }
  .data-table .up { color: var(--green); }
  .data-table .dn { color: var(--red); }
  .data-table .highlight { color: var(--accent); font-weight: 600; }
  .bar-cell { display: flex; align-items: center; gap: 8px; }
  .bar-track { flex: 1; height: 4px; background: var(--surface2); border-radius: 2px; }
  .bar-fill { height: 4px; border-radius: 2px; background: var(--accent); }

  /* FINDINGS */
  .findings-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }
  .finding-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 20px 18px;
    display: flex;
    gap: 16px;
    align-items: flex-start;
  }
  .finding-number {
    font-size: 28px;
    font-weight: 800;
    color: var(--accent);
    opacity: 0.5;
    line-height: 1;
    flex-shrink: 0;
    width: 32px;
  }
  .finding-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 6px;
  }
  .finding-body {
    font-size: 12px;
    color: var(--text-muted);
    line-height: 1.5;
  }
  .finding-body strong { color: var(--text); }

  /* INLINE PILLS */
  .pill {
    display: inline-block;
    padding: 1px 8px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 600;
  }
  .pill-blue { background: rgba(79,142,247,0.15); color: var(--accent); }
  .pill-green { background: rgba(79,212,160,0.15); color: var(--accent3); }
  .pill-amber { background: rgba(247,196,79,0.15); color: var(--accent2); }
  .pill-red { background: rgba(247,113,79,0.15); color: var(--accent4); }

  /* ANNOTATION CALLOUT */
  .callout {
    background: rgba(79,142,247,0.07);
    border-left: 3px solid var(--accent);
    border-radius: 0 8px 8px 0;
    padding: 12px 16px;
    margin: 16px 0;
    font-size: 12px;
    color: var(--text-muted);
  }
  .callout strong { color: var(--text); }

  /* FOOTER */
  .report-footer {
    padding: 32px 64px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 11px;
    color: var(--text-muted);
  }

  @media (max-width: 1100px) {
    .kpi-grid { grid-template-columns: repeat(3, 1fr); }
    .chart-grid-2, .chart-grid-3 { grid-template-columns: 1fr; }
    .findings-grid { grid-template-columns: 1fr; }
    .container { padding: 0 24px; }
    .report-header { padding: 36px 24px 28px; }
    .header-title { font-size: 26px; }
  }
</style>
</head>
<body>

<!-- ═══════════════════════════════════════════════════════════════ HEADER -->
<div class="report-header">
  <div class="header-label">Energy Policy Research &bull; Trend Analysis</div>
  <div class="header-title">Global Fuel Price Trends &amp;<br>Policy Impact Analysis</div>
  <div class="header-subtitle">A comprehensive analysis of retail fuel prices across 84 countries, examining the interplay between Brent Crude benchmarks, taxation, subsidies, and regional economic conditions over a six-year period (2020–2026).</div>
  <div class="header-meta">
    <span><strong>Coverage:</strong> 84 Countries · 7 Regions</span>
    <span><strong>Period:</strong> January 2020 – April 2026</span>
    <span><strong>Observations:</strong> 27,468 Weekly Records</span>
    <span><strong>Data Source:</strong> Kaggle / Global Energy Ministries, EIA, OPEC, World Bank</span>
    <span><strong>Published:</strong> April 2026</span>
  </div>
</div>

<div class="container">

<!-- ═══════════════════════════════════════════════════════ SECTION 1: OVERVIEW -->
<div class="section">
  <div class="section-header">
    <span class="section-number">01</span>
    <h2 class="section-title">Global Fuel Price Overview</h2>
  </div>
  <p class="section-desc">High-level summary statistics for petrol, diesel, and LPG across all 84 countries and 328+ weeks. Brent Crude serves as the commodity baseline against which retail prices are indexed.</p>

  <!-- KPI Row -->
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-label">Avg Retail Petrol</div>
      <div class="kpi-value">$2.28</div>
      <div class="kpi-sub">USD per liter · all countries</div>
      <span class="kpi-badge badge-up">Range $0.01 – $6.78</span>
    </div>
    <div class="kpi-card accent2">
      <div class="kpi-label">Avg Retail Diesel</div>
      <div class="kpi-value">$2.13</div>
      <div class="kpi-sub">USD per liter · all countries</div>
      <span class="kpi-badge badge-up">Δ $0.15 below petrol</span>
    </div>
    <div class="kpi-card accent3">
      <div class="kpi-label">Avg Retail LPG</div>
      <div class="kpi-value">$1.71</div>
      <div class="kpi-sub">USD per liter · all countries</div>
      <span class="kpi-badge badge-up">25% below petrol</span>
    </div>
    <div class="kpi-card accent4">
      <div class="kpi-label">Mean Brent Crude</div>
      <div class="kpi-value">$106.69</div>
      <div class="kpi-sub">USD per barrel · period avg</div>
      <span class="kpi-badge badge-up">Range $47.97 – $130.00</span>
    </div>
    <div class="kpi-card red">
      <div class="kpi-label">Brent–Retail Corr.</div>
      <div class="kpi-value">r=0.9999</div>
      <div class="kpi-sub">Petrol vs Brent (weekly avg)</div>
      <span class="kpi-badge badge-up">Near-perfect coupling</span>
    </div>
  </div>

  <!-- Summary Table by Year -->
  <div class="chart-box full-width" style="margin-bottom:24px;">
    <div class="chart-title">Annual Average Prices (USD/Liter) — Petrol, Diesel &amp; LPG vs Brent Crude</div>
    <div class="chart-subtitle">Cross-country mean retail prices per year, alongside Brent Crude benchmark (right axis)</div>
    <div class="chart-wrapper" style="height:300px;">
      <canvas id="annualChart"></canvas>
    </div>
  </div>

  <div class="callout">
    <strong>Data integrity note:</strong> The <code>tax_percentage</code> field shows significant within-country week-to-week variability (e.g., United States ranges from 11.5% to 65.0% in available sample). This likely reflects estimation methodology rather than actual weekly tax changes; tax figures should be interpreted as indicative averages rather than precise statutory rates.
  </div>
</div>

<!-- ═════════════════════════════════════════════ SECTION 2: TEMPORAL TRENDS -->
<div class="section">
  <div class="section-header">
    <span class="section-number">02</span>
    <h2 class="section-title">Temporal Price Trends &amp; Volatility</h2>
  </div>
  <p class="section-desc">Weekly and monthly price trajectories from January 2020 through April 2026. The analysis captures three major disruptions: the COVID-19 demand collapse (Mar–May 2020), the post-pandemic energy crisis and geopolitical shock (2022), and sustained elevated prices through 2024–2026.</p>

  <div class="chart-grid-2" style="margin-bottom:24px;">
    <!-- Brent Crude Timeline -->
    <div class="chart-box">
      <div class="chart-title">Brent Crude Price Timeline (Monthly Average)</div>
      <div class="chart-subtitle">USD per barrel · Jan 2020 – Apr 2026</div>
      <div class="chart-wrapper" style="height:260px;">
        <canvas id="brentTimelineChart"></canvas>
      </div>
    </div>
    <!-- Petrol & Diesel Monthly -->
    <div class="chart-box">
      <div class="chart-title">Global Mean Retail Petrol &amp; Diesel (Monthly)</div>
      <div class="chart-subtitle">USD per liter · cross-country average</div>
      <div class="chart-wrapper" style="height:260px;">
        <canvas id="retailTimelineChart"></canvas>
      </div>
    </div>
  </div>

  <!-- Year-over-year change table -->
  <div class="chart-box full-width" style="margin-bottom:24px;">
    <div class="chart-title">Year-over-Year Price Change Analysis</div>
    <div class="chart-subtitle">Annual mean prices and percentage change vs prior year</div>
    <table class="data-table">
      <thead>
        <tr>
          <th>Year</th>
          <th>Brent Crude (USD/bbl)</th>
          <th>YoY Brent Δ</th>
          <th>Petrol (USD/L)</th>
          <th>YoY Petrol Δ</th>
          <th>Diesel (USD/L)</th>
          <th>LPG (USD/L)</th>
          <th>Key Event</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td>2020</td>
          <td class="num">$69.44</td>
          <td class="dn">—</td>
          <td class="num">$1.485</td>
          <td class="dn">—</td>
          <td class="num">$1.389</td>
          <td class="num">$1.114</td>
          <td><span class="pill pill-red">COVID-19 Demand Collapse</span></td>
        </tr>
        <tr>
          <td>2021</td>
          <td class="num">$106.59</td>
          <td class="up">+53.5%</td>
          <td class="num">$2.280</td>
          <td class="up">+53.5%</td>
          <td class="num">$2.131</td>
          <td class="num">$1.710</td>
          <td><span class="pill pill-blue">Post-Pandemic Recovery</span></td>
        </tr>
        <tr>
          <td>2022</td>
          <td class="num">$117.12</td>
          <td class="up">+9.9%</td>
          <td class="num">$2.505</td>
          <td class="up">+9.9%</td>
          <td class="num">$2.342</td>
          <td class="num">$1.879</td>
          <td><span class="pill pill-red">Geopolitical Energy Crisis</span></td>
        </tr>
        <tr>
          <td>2023</td>
          <td class="num">$104.43</td>
          <td class="dn">−10.8%</td>
          <td class="num">$2.234</td>
          <td class="dn">−10.9%</td>
          <td class="num">$2.089</td>
